# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), ключ сверен с ответами учебника (№336, 338) и вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_18_336_a", r"$t=x+\frac1x$: $2(t^{2}-2)-t=2\Rightarrow2t^{2}-t-6=0$, $t=2$ или $t=-\frac32$; $x+\frac1x=2\Rightarrow x=1$; $x+\frac1x=-\frac32\Rightarrow2x^{2}+3x+2=0$, $D=-7<0$ — корней нет (ответ учебника: «а) $1$»). В ключе стояли ещё $-\frac12$ и $-2$: при $x=-2$ левая часть равна $11\ne2$",
  k=r"$x = 1$",
  dnew={0: (r"$x = 1$; $x = -1$", r"Ученик верно решил $x+\frac1x=2$ ($x=1$), а для $t=-\frac32$ принял, что подойдёт $x=-1$; но при $x=-1$ левая часть равна $2\cdot2+2=6\ne2$, а уравнение $x+\frac1x=-\frac32$ корней не имеет."),
        1: (r"$x = 1$; $x = -\dfrac{1}{2}$; $x = -2$", r"Ученик для $t=-\frac32$ записал $x+\frac1x=-\frac32$ как $2x^{2}+5x+2=0$ (ошибка при умножении на $2x$) и получил $x=-\frac12$, $x=-2$; верно $2x^{2}+3x+2=0$, $D<0$."),
        2: (r"$x = 1$; $x = \dfrac{1}{2}$; $x = 2$", r"Ученик решил уравнение $2t^{2}-t-6=0$ неверно и получил $t=2$ и $t=\frac52$; тогда $x+\frac1x=\frac52$ даёт $x=2$ и $x=\frac12$, но верно $t=-\frac32$, что корней не даёт.")})
E("G9_TB_18_338_a", r"$t=x+\frac1x$: $t^{3}-3t=22t\Rightarrow t(t^{2}-25)=0$, $t=\pm5$ ($t=0$ невозможно); $x+\frac1x=5\Rightarrow x=\frac{5\pm\sqrt{21}}{2}$; $x+\frac1x=-5\Rightarrow x=\frac{-5\pm\sqrt{21}}{2}$ (ответ учебника: $\pm2{,}5\pm\sqrt{5{,}25}$). Ключ $\pm2\pm\sqrt3$ соответствует $x+\frac1x=\pm4$",
  k=r"$x = \dfrac{5 \pm \sqrt{21}}{2}$; $x = \dfrac{-5 \pm \sqrt{21}}{2}$",
  dnew={0: (r"$x = -2 \pm \sqrt{3}$; $x = 2 \pm \sqrt{3}$", r"Ученик нашёл $t^{2}=16$ вместо $t^{2}=25$ (ошибка в формуле $x^{3}+\frac1{x^{3}}=t^{3}-3t$) и получил $x+\frac1x=\pm4$."),
        1: (r"$x = \dfrac{5 \pm \sqrt{21}}{2}$", r"Ученик решил только $x+\frac1x=5$ и потерял случай $t=-5$: $x+\frac1x=-5$ даёт ещё два корня $\frac{-5\pm\sqrt{21}}{2}$."),
        2: (r"$x = \pm 3$; $x = \pm\dfrac{1}{3}$", r"Ученик умножил уравнение на $x^{3}$ и неверно разложил многочлен шестой степени, угадав корни $\pm3$, $\pm\frac13$; подстановка $x=3$ не даёт тождества: $27+\frac1{27}\ne22\left(3+\frac13\right)$.")})
